    faq_title: 'الأسئلة الشائعة', faq_q1: 'كيف أنشر عقاراً؟', faq_a1: 'أنشئ حساباً، انقر على "نشر عقار" واملأ النموذج. يبقى إعلانك "قيد المراجعة" حتى تتم الموافقة عليه من قبل فريقنا.', faq_q2: 'هل النشر مجاني؟', faq_a2: 'بالنسبة للمستخدمين الأفراد، نعم — النشر مجاني لغاية 3 إعلانات. بالنسبة للوكالات، تبلغ تكلفة النشر 15 يورو شهرياً، مع الحق في نشر حتى 50 إعلاناً في آن واحد.', faq_q3: 'كيف أتواصل مع معلن العقار؟', faq_a3: 'في صفحة العقار، استخدم نموذج الاتصال — إذا كنت مسجلاً الدخول، تُحفظ المحادثة في دردشتك.', faq_q4: 'هل يمكنني تعديل أو حذف إعلان بعد نشره؟', faq_a4: 'نعم، في لوحتك ستجد خيارات لتعديل أو إلغاء تفعيل أو حذف كل إعلان.', faq_q5: 'ما هو "إبراز" الإعلان؟', faq_a5: 'إنها طريقة لإعطاء عقارك مزيداً من الظهور في نتائج البحث. يمكنك تفعيلها مباشرة من لوحتك.', faq_q6: 'كيف أبلغ عن إعلان مشبوه؟', faq_a6: 'في صفحة العقار، يوجد زر "الإبلاغ عن هذا الإعلان". يقوم فريقنا بمراجعة جميع البلاغات.',
    attr_faq_title: 'الأسئلة الشائعة', attr_remove_compare: 'إزالة من المقارنة', attr_delete_conversation: 'حذف المحادثة', attr_delete_conv_permanent: 'حذف هذه المحادثة نهائياً', attr_delete_message: 'حذف الرسالة', attr_delete_message_unseen: 'حذف الرسالة (لم تُشاهد بعد)', attr_write_message: 'اكتب رسالة...', attr_search_name_email: 'الاسم أو البريد الإلكتروني أو العقار', attr_photo_conversation: 'صورة عقار المحادثة', attr_back_to_conversations: 'العودة إلى قائمة المحادثات', attr_remove_favorites: 'إزالة من المفضلة', attr_save_favorites: 'حفظ في المفضلة', attr_profile_photo_alt: 'صورة ملفك الشخصي', attr_verified_professional: 'محترف موثّق', attr_close_alert: 'إغلاق التنبيه', attr_street_number: 'الشارع، الرقم...', attr_from: 'من', attr_parish: 'الأبرشية', attr_municipality: 'البلدية', attr_write_here: 'اكتب هنا', attr_floorplan_alt: 'مخطط العقار', attr_interest_placeholder: 'مرحباً، أنا مهتم بهذا العقار...', attr_notifications: 'الإشعارات', attr_close: 'إغلاق',
